args.content:
import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">{enabled ? 'Turn off' : 'Turn on'}</button>
      </form>
    </main>
  )
}

